/**
 * @param {Function} fn
 * @param {Array} args
 * @return {Function}
 */
var partial = function(fn, args) {
    return function(...restArgs) {
        const newArgs = [];
        // Pointer to the next unused value in restArgs
        let restIdx = 0;
        // Fill placeholders with restArgs in order
        for (const value of args) {
            if (value === "_") {
                newArgs.push(restArgs[restIdx++]);
            } else {
                newArgs.push(value);
            }
        }
        // Append any leftover restArgs
        for (; restIdx < restArgs.length; restIdx++) {
            newArgs.push(restArgs[restIdx]);
        }
        // Call fn with the arguments spread out
        return fn(...newArgs);
    };
};
